import{_ as a,o as e,c as t,V as r}from"./chunks/framework.12adfae7.js";const m=JSON.parse('{"title":"生成式ai","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/ai/生成式ai.md","filePath":"blogs/ai/生成式ai.md"}'),o={name:"blogs/ai/生成式ai.md"},i=r('<h1 id="生成式ai" tabindex="-1">生成式ai <a class="header-anchor" href="#生成式ai" aria-label="Permalink to &quot;生成式ai&quot;">​</a></h1><h2 id="多维数据向量存储词性" tabindex="-1">多维数据向量存储词性 <a class="header-anchor" href="#多维数据向量存储词性" aria-label="Permalink to &quot;多维数据向量存储词性&quot;">​</a></h2><h2 id="自注意力" tabindex="-1">自注意力 <a class="header-anchor" href="#自注意力" aria-label="Permalink to &quot;自注意力&quot;">​</a></h2><p>避免生成错误</p><h2 id="rag、微调-后训练" tabindex="-1">rag、微调（后训练） <a class="header-anchor" href="#rag、微调-后训练" aria-label="Permalink to &quot;rag、微调（后训练）&quot;">​</a></h2><h2 id="合同审查" tabindex="-1">合同审查 <a class="header-anchor" href="#合同审查" aria-label="Permalink to &quot;合同审查&quot;">​</a></h2><p>ChatGPT LLM（Legal Language Models）是一种利用自然语言处理和机器学习技术来处理法律文本的方法。实现AI合同审查的步骤可能包括以下几个方面：</p><p>数据收集和准备：</p><p>收集大量的合同文本数据，包括各种类型的合同，如租赁合同、销售合同、服务合同等。 清洗和标记数据，确保数据格式一致，并为模型提供适当的标签，如合同类型、条款等。 模型选择和训练：</p><p>选择合适的LLM模型，如BERT、GPT等，并进行预训练或微调，以适应合同审查的任务。 使用已标记的合同数据来训练模型，使其能够理解和分析合同中的文本内容，识别关键条款、风险和潜在问题。 特征工程和模型优化：</p><p>针对合同审查的特定任务，进行特征工程，提取合适的文本特征，如关键词、实体识别等。 优化模型结构和参数，以提高模型在合同审查任务上的性能和准确性。 模型部署和集成：</p><p>将训练好的模型部署到合同审查系统中，确保其能够处理实时的合同文本数据。 集成模型与其他相关系统或工具，如合同管理系统、工作流程管理工具等，实现合同审查流程的自动化和优化。 测试和评估：</p><p>对部署的模型进行测试，评估其在真实场景下的性能和效果。 根据评估结果对模型进行调整和优化，以提高其在合同审查任务中的表现。 持续改进和更新：</p><p>定期监控模型的性能和准确性，收集用户反馈，并根据需要进行模型更新和改进。 不断改进合同审查系统的功能和性能，以应对新的法律要求和业务需求。 以上步骤涵盖了实现AI合同审查的基本计划，但具体的实施可能会根据实际情况和需求进行调整和补充。</p>',14),s=[i];function l(n,h,_,c,d,p){return e(),t("div",null,s)}const b=a(o,[["render",l]]);export{m as __pageData,b as default};
